A<!DOCTYPE html>
<html lang="en" data-theme="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ilyas Yekhlef — Digital Development Student &amp; Aspiring Web Developer</title>
<meta name="description" content="Portfolio of Ilyas Yekhlef, a Digital Development student from Tangier, Morocco, learning web development, databases, cybersecurity and building practical projects.">
<meta name="theme-color" content="#060810">

<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap" rel="stylesheet">

<style>
  /* ============ RESET ============ */
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  img,svg{display:block;max-width:100%}
  button{font:inherit;cursor:pointer;background:none;border:none;color:inherit}
  a{color:inherit;text-decoration:none}
  ul{list-style:none}
  input,textarea{font:inherit;color:inherit}

  /* ============ TOKENS ============ */
  :root{
    --bg:#060810;
    --bg-alt:#0a0d18;
    --surface:rgba(255,255,255,0.045);
    --surface-strong:rgba(255,255,255,0.07);
    --border:rgba(255,255,255,0.09);
    --border-strong:rgba(255,255,255,0.16);
    --text:#eef1f8;
    --text-muted:#96a0b8;
    --text-faint:#5e6882;
    --blue:#4f7dff;
    --blue-bright:#6d93ff;
    --blue-glow:rgba(79,125,255,0.35);
    --violet:#9b7bff;
    --violet-glow:rgba(155,123,255,0.28);
    --gold:#d9b26a;
    --success:#3fd68a;
    --danger:#ff6b6b;
    --font-display:'Space Grotesk',sans-serif;
    --font-body:'Inter',sans-serif;
    --font-mono:'JetBrains Mono',monospace;
    --radius-s:10px;
    --radius-m:16px;
    --radius-l:24px;
    --maxw:1180px;
    --nav-h:76px;
    --ease:cubic-bezier(.19,1,.22,1);
  }
  html[data-theme="light"]{
    --bg:#f5f7fb;
    --bg-alt:#ffffff;
    --surface:rgba(10,16,32,0.035);
    --surface-strong:rgba(10,16,32,0.06);
    --border:rgba(10,16,32,0.09);
    --border-strong:rgba(10,16,32,0.16);
    --text:#0d1220;
    --text-muted:#4d566e;
    --text-faint:#8890a4;
    --blue:#2f5fe0;
    --blue-bright:#2452c9;
    --blue-glow:rgba(47,95,224,0.18);
    --violet:#7a53e6;
    --violet-glow:rgba(122,83,230,0.16);
    --gold:#b4863a;
  }

  body{
    background:var(--bg);
    color:var(--text);
    font-family:var(--font-body);
    line-height:1.65;
    -webkit-font-smoothing:antialiased;
    overflow-x:hidden;
    transition:background .4s var(--ease),color .4s var(--ease);
  }

  h1,h2,h3,h4{font-family:var(--font-display);line-height:1.15;letter-spacing:-0.01em;font-weight:600}
  h1{font-size:clamp(2.4rem,5.2vw,4.2rem);font-weight:700;letter-spacing:-0.02em}
  h2{font-size:clamp(1.9rem,3.4vw,2.6rem)}
  h3{font-size:1.3rem}
  p{color:var(--text-muted)}
  .mono{font-family:var(--font-mono)}

  .container{max-width:var(--maxw);margin:0 auto;padding:0 1.5rem}
  section{padding:7rem 0}
  @media(max-width:700px){section{padding:4.5rem 0}}

  .section-head{margin-bottom:3.2rem;max-width:640px}
  .section-tag{
    font-family:var(--font-mono);font-size:.8rem;color:var(--blue-bright);
    display:flex;align-items:center;gap:.6rem;margin-bottom:.9rem;
  }
  .section-tag::before{content:"";width:18px;height:1px;background:var(--blue-bright)}
  .section-head p{margin-top:.9rem;font-size:1.05rem}

  ::selection{background:var(--blue-glow);color:var(--text)}

  /* focus visibility */
  a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{
    outline:2px solid var(--blue-bright);outline-offset:3px;border-radius:4px;
  }

  @media (prefers-reduced-motion: reduce){
    *{animation-duration:0.001ms !important;animation-iteration-count:1 !important;transition-duration:0.001ms !important;scroll-behavior:auto !important}
  }

  /* ============ BUTTONS ============ */
  .btn{
    display:inline-flex;align-items:center;gap:.55rem;
    padding:.85rem 1.5rem;border-radius:999px;font-weight:600;font-size:.92rem;
    transition:transform .25s var(--ease), box-shadow .25s var(--ease), background .25s var(--ease), border-color .25s var(--ease);
    white-space:nowrap;
  }
  .btn-primary{
    background:linear-gradient(135deg,var(--blue),var(--violet));
    color:#fff;box-shadow:0 8px 30px -8px var(--blue-glow);
  }
  .btn-primary:hover{transform:translateY(-2px);box-shadow:0 14px 36px -8px var(--blue-glow)}
  .btn-ghost{
    border:1px solid var(--border-strong);color:var(--text);background:var(--surface);
  }
  .btn-ghost:hover{border-color:var(--blue-bright);background:var(--surface-strong);transform:translateY(-2px)}
  .btn-sm{padding:.6rem 1.1rem;font-size:.85rem}

  /* ============ NAVBAR ============ */
  .navbar{
    position:fixed;top:0;left:0;right:0;z-index:100;
    height:var(--nav-h);display:flex;align-items:center;
    transition:background .35s var(--ease), border-color .35s var(--ease), backdrop-filter .35s var(--ease);
    border-bottom:1px solid transparent;
  }
  .navbar.scrolled{
    background:color-mix(in srgb, var(--bg) 78%, transparent);
    backdrop-filter:blur(14px) saturate(140%);
    border-bottom:1px solid var(--border);
  }
  .nav-inner{width:100%;display:flex;align-items:center;justify-content:space-between;gap:1rem}
  .brand{display:flex;align-items:center;gap:.7rem;font-weight:600}
  .brand-mark{
    width:38px;height:38px;border-radius:10px;display:flex;align-items:center;justify-content:center;
    background:linear-gradient(135deg,var(--blue),var(--violet));
    font-family:var(--font-mono);font-size:.78rem;font-weight:600;color:#fff;flex-shrink:0;
  }
  .brand-text{font-family:var(--font-display);font-size:1.02rem}
  .brand-text span{color:var(--text-muted);font-weight:500}

  .nav-links{display:flex;align-items:center;gap:1.6rem}
  @media(min-width:1180px){.nav-links{gap:2.1rem}}
  .nav-links a{
    position:relative;font-size:.92rem;color:var(--text-muted);font-weight:500;
    padding:.3rem 0;transition:color .25s;
  }
  .nav-links a::after{
    content:"";position:absolute;left:0;bottom:-4px;width:0;height:2px;
    background:linear-gradient(90deg,var(--blue),var(--violet));
    transition:width .3s var(--ease);
  }
  .nav-links a:hover{color:var(--text)}
  .nav-links a.active{color:var(--text)}
  .nav-links a.active::after{width:100%}

  .nav-right{display:flex;align-items:center;gap:.9rem}
  .theme-toggle{
    width:38px;height:38px;border-radius:50%;border:1px solid var(--border-strong);
    display:flex;align-items:center;justify-content:center;background:var(--surface);
    transition:border-color .25s, transform .25s;
  }
  .theme-toggle:hover{border-color:var(--blue-bright);transform:rotate(20deg)}
  .theme-toggle svg{width:17px;height:17px}
  .icon-sun{display:none}
  html[data-theme="light"] .icon-moon{display:none}
  html[data-theme="light"] .icon-sun{display:block}

  .nav-toggle{display:none;width:38px;height:38px;position:relative}
  .nav-toggle span{
    position:absolute;left:9px;right:9px;height:2px;background:var(--text);
    transition:transform .3s var(--ease), opacity .3s var(--ease), top .3s var(--ease);
  }
  .nav-toggle span:nth-child(1){top:13px}
  .nav-toggle span:nth-child(2){top:19px}
  .nav-toggle span:nth-child(3){top:25px}
  .nav-toggle.open span:nth-child(1){top:19px;transform:rotate(45deg)}
  .nav-toggle.open span:nth-child(2){opacity:0}
  .nav-toggle.open span:nth-child(3){top:19px;transform:rotate(-45deg)}

  @media(max-width:1040px){
    .nav-links{
      position:fixed;top:var(--nav-h);left:0;right:0;flex-direction:column;align-items:flex-start;
      gap:0;background:var(--bg-alt);border-bottom:1px solid var(--border);
      padding:.5rem 1.5rem 1.2rem;transform:translateY(-8px);opacity:0;pointer-events:none;
      transition:opacity .3s var(--ease), transform .3s var(--ease);
    }
    .nav-links.open{opacity:1;pointer-events:auto;transform:translateY(0)}
    .nav-links a{width:100%;padding:.85rem 0;border-bottom:1px solid var(--border)}
    .nav-links a:last-child{border-bottom:none}
    .nav-links a::after{display:none}
    .nav-cta{display:none !important}
    .nav-toggle{display:block}
  }

  /* ============ HERO ============ */
  .hero{
    min-height:100vh;display:flex;align-items:center;padding-top:calc(var(--nav-h) + 2rem);
    position:relative;overflow:hidden;
  }
  .hero::before,.hero::after{
    content:"";position:absolute;border-radius:50%;filter:blur(90px);opacity:.35;z-index:0;
  }
  .hero::before{width:480px;height:480px;background:var(--blue);top:-140px;right:-100px}
  .hero::after{width:380px;height:380px;background:var(--violet);opacity:.22;bottom:-120px;left:-80px}
  .hero-grid{
    position:relative;z-index:1;display:grid;grid-template-columns:1.05fr .95fr;gap:3.5rem;align-items:center;
  }
  @media(max-width:960px){.hero-grid{grid-template-columns:1fr;gap:3rem}}

  .badge{
    display:inline-flex;align-items:center;gap:.55rem;padding:.5rem 1rem;border-radius:999px;
    background:var(--surface);border:1px solid var(--border);font-family:var(--font-mono);
    font-size:.78rem;color:var(--text-muted);margin-bottom:1.6rem;
  }
  .badge .dot{width:7px;height:7px;border-radius:50%;background:var(--success);box-shadow:0 0 0 3px rgba(63,214,138,.18);animation:pulse 2.4s infinite}
  @keyframes pulse{0%,100%{box-shadow:0 0 0 3px rgba(63,214,138,.18)}50%{box-shadow:0 0 0 6px rgba(63,214,138,.05)}}

  .hero-eyebrow{font-family:var(--font-mono);color:var(--blue-bright);font-size:.95rem;margin-bottom:1rem}
  .hero h1{margin-bottom:1.1rem}
  .hero h1 .highlight{
    background:linear-gradient(120deg,var(--blue-bright),var(--violet));
    -webkit-background-clip:text;background-clip:text;color:transparent;
  }
  .hero-sub{font-size:1.15rem;color:var(--text);font-weight:500;margin-bottom:1rem;font-family:var(--font-display)}

  /* ---- identity block (name / location / rotating role) ---- */
  .identity-row{display:flex;align-items:center;gap:.9rem;flex-wrap:wrap;margin-bottom:1.5rem}
  .location-tag{
    display:inline-flex;align-items:center;gap:.45rem;padding:.4rem .85rem .4rem .6rem;
    border-radius:999px;background:var(--surface);border:1px solid var(--border);
    font-family:var(--font-mono);font-size:.78rem;color:var(--text-muted);
  }
  .location-tag svg{width:13px;height:13px;color:var(--gold);flex-shrink:0}
  .identity-row .divider-dot{width:4px;height:4px;border-radius:50%;background:var(--text-faint)}

  .name-stack{margin-bottom:.7rem}
  .name-stack .line1{
    display:block;font-family:var(--font-display);font-weight:500;
    font-size:clamp(1.3rem,2.4vw,1.6rem);color:var(--text-muted);letter-spacing:0;
  }
  .name-stack .line2{
    display:block;font-family:var(--font-display);font-weight:700;
    font-size:clamp(2.8rem,6.2vw,4.6rem);letter-spacing:-0.02em;line-height:1;
    background:linear-gradient(120deg,var(--text) 40%,var(--blue-bright) 75%,var(--violet));
    -webkit-background-clip:text;background-clip:text;color:transparent;
  }

  .role-line{
    display:flex;align-items:center;gap:.7rem;margin-bottom:1.4rem;
    font-family:var(--font-mono);font-size:1.02rem;color:var(--text);
  }
  .role-line .bracket{color:var(--blue-bright)}
  .role-word{
    display:inline-block;color:var(--violet);font-weight:500;
    transition:opacity .35s var(--ease), transform .35s var(--ease);
  }
  .role-word.swap{opacity:0;transform:translateY(6px)}
  .hero-desc{max-width:520px;margin-bottom:2.2rem;font-size:1.02rem}
  .hero-actions{display:flex;flex-wrap:wrap;gap:.9rem}

  /* terminal visual */
  .terminal{
    background:var(--bg-alt);border:1px solid var(--border-strong);border-radius:var(--radius-m);
    overflow:hidden;box-shadow:0 30px 70px -30px rgba(0,0,0,.6);
    position:relative;
  }
  .terminal-bar{
    display:flex;align-items:center;gap:.4rem;padding:.85rem 1rem;border-bottom:1px solid var(--border);
    background:var(--surface);
  }
  .terminal-bar span{width:11px;height:11px;border-radius:50%}
  .terminal-bar span:nth-child(1){background:#ff5f57}
  .terminal-bar span:nth-child(2){background:#febc2e}
  .terminal-bar span:nth-child(3){background:#28c840}
  .terminal-title{margin-left:auto;font-family:var(--font-mono);font-size:.72rem;color:var(--text-faint)}
  .terminal-body{padding:1.4rem 1.3rem 1.6rem;font-family:var(--font-mono);font-size:.86rem;min-height:290px}
  .terminal-line{margin-bottom:.75rem;color:var(--text-muted);white-space:pre-wrap}
  .terminal-line .prompt{color:var(--success)}
  .terminal-line .path{color:var(--blue-bright)}
  .terminal-line .out{color:var(--text)}
  .terminal-line .ok{color:var(--success)}
  .cursor{display:inline-block;width:7px;height:15px;background:var(--blue-bright);vertical-align:middle;animation:blink 1s step-end infinite}
  @keyframes blink{50%{opacity:0}}
  .float-icons{position:absolute;inset:0;pointer-events:none}
  .float-icons span{
    position:absolute;font-family:var(--font-mono);font-size:.72rem;font-weight:600;
    padding:.3rem .55rem;border-radius:8px;border:1px solid var(--border-strong);
    background:var(--surface);color:var(--text-muted);opacity:.9;
    animation:float 6s ease-in-out infinite;
  }
  .float-icons span:nth-child(1){top:-14px;left:-14px;animation-delay:0s;color:#e34f26}
  .float-icons span:nth-child(2){top:20%;right:-22px;animation-delay:1.2s;color:#2965f1}
  .float-icons span:nth-child(3){bottom:18%;left:-26px;animation-delay:2.4s;color:#f0db4f}
  .float-icons span:nth-child(4){bottom:-16px;right:10%;animation-delay:.6s;color:#3776ab}
  @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}
  @media(max-width:960px){.float-icons{display:none}}

  /* ---- photo hero visual ---- */
  .photo-stage{position:relative;width:100%;max-width:420px;margin:0 auto}
  .photo-glow{
    position:absolute;inset:-30px;background:conic-gradient(from 180deg,var(--blue),var(--violet),var(--gold),var(--blue));
    filter:blur(46px);opacity:.35;border-radius:50%;z-index:0;animation:spin 14s linear infinite;
  }
  @keyframes spin{to{transform:rotate(360deg)}}
  .photo-frame{
    position:relative;z-index:1;border-radius:44% 56% 58% 42% / 46% 40% 60% 54%;
    overflow:hidden;border:1px solid var(--border-strong);
    box-shadow:0 30px 70px -25px rgba(0,0,0,.65);
    background:var(--bg-alt);
    aspect-ratio:1/1;
  }
  .photo-frame img{width:100%;height:100%;object-fit:cover;display:block}
  .mini-terminal{
    position:absolute;left:-8%;bottom:-9%;z-index:2;width:64%;min-width:210px;
    background:var(--bg-alt);border:1px solid var(--border-strong);border-radius:var(--radius-m);
    box-shadow:0 20px 44px -18px rgba(0,0,0,.6);overflow:hidden;
  }
  .mini-terminal .terminal-bar{padding:.55rem .75rem}
  .mini-terminal .terminal-bar span{width:8px;height:8px}
  .mini-terminal-body{padding:.9rem 1rem 1.05rem;font-family:var(--font-mono);font-size:.72rem;color:var(--text-muted)}
  .mini-terminal-body .prompt{color:var(--success)}
  .mini-terminal-body .out{color:var(--text);display:block;margin-top:.25rem}
  .mini-terminal-body .ok{color:var(--success);display:block;margin-top:.5rem}
  .avail-chip{
    position:absolute;top:6%;right:-6%;z-index:2;display:flex;align-items:center;gap:.4rem;
    padding:.5rem .85rem;border-radius:999px;background:var(--bg-alt);
    border:1px solid var(--border-strong);box-shadow:0 14px 30px -14px rgba(0,0,0,.55);
    font-family:var(--font-mono);font-size:.7rem;color:var(--text-muted);
  }
  .avail-chip .dot{width:6px;height:6px;border-radius:50%;background:var(--success)}
  @media(max-width:960px){
    .photo-stage{max-width:300px}
    .mini-terminal{width:70%;min-width:170px;left:-4%;bottom:-7%}
    .mini-terminal-body{font-size:.66rem;padding:.7rem .8rem .85rem}
    .avail-chip{right:0}
  }
  @media(max-width:420px){
    .mini-terminal{position:static;width:100%;margin-top:1.2rem}
    .avail-chip{top:-10px;right:0}
  }

  /* ============ REVEAL ============ */
  .reveal{opacity:0;transform:translateY(22px);transition:opacity .7s var(--ease), transform .7s var(--ease)}
  .reveal.in-view{opacity:1;transform:translateY(0)}
  .reveal-stagger.in-view > *{opacity:1;transform:translateY(0)}
  .reveal-stagger > *{opacity:0;transform:translateY(18px);transition:opacity .6s var(--ease), transform .6s var(--ease)}
  .reveal-stagger.in-view > *:nth-child(1){transition-delay:.05s}
  .reveal-stagger.in-view > *:nth-child(2){transition-delay:.12s}
  .reveal-stagger.in-view > *:nth-child(3){transition-delay:.19s}
  .reveal-stagger.in-view > *:nth-child(4){transition-delay:.26s}
  .reveal-stagger.in-view > *:nth-child(5){transition-delay:.33s}
  .reveal-stagger.in-view > *:nth-child(6){transition-delay:.4s}
  .reveal-stagger.in-view > *:nth-child(7){transition-delay:.47s}

  /* ============ ABOUT ============ */
  .about-grid{display:grid;grid-template-columns:1fr 1fr;gap:3.5rem;align-items:start}
  @media(max-width:900px){.about-grid{grid-template-columns:1fr;gap:2.5rem}}
  .about-text p{margin-bottom:1.1rem;font-size:1.02rem}
  .about-side .terminal .terminal-body{min-height:190px}
  .stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
  .stat-card{
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-m);
    padding:1.5rem;transition:border-color .3s, transform .3s;
  }
  .stat-card:hover{border-color:var(--blue-bright);transform:translateY(-3px)}
  .stat-num{font-family:var(--font-display);font-size:1.9rem;font-weight:700;
    background:linear-gradient(120deg,var(--blue-bright),var(--violet));
    -webkit-background-clip:text;background-clip:text;color:transparent;}
  .stat-label{font-size:.85rem;color:var(--text-muted);margin-top:.3rem}

  /* ============ SKILLS ============ */
  .tabs{display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:2.2rem;border-bottom:1px solid var(--border);padding-bottom:1.1rem}
  .tab-btn{
    padding:.55rem 1.1rem;border-radius:999px;font-size:.88rem;font-weight:500;color:var(--text-muted);
    border:1px solid transparent;transition:all .25s var(--ease);
  }
  .tab-btn:hover{color:var(--text)}
  .tab-btn.active{background:var(--surface-strong);border-color:var(--border-strong);color:var(--text)}
  .skills-panel{display:none;grid-template-columns:repeat(2,1fr);gap:1rem}
  .skills-panel.active{display:grid}
  @media(max-width:700px){.skills-panel{grid-template-columns:1fr}}
  .skill-card{
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-m);
    padding:1.25rem 1.4rem;transition:border-color .3s, transform .3s;
  }
  .skill-card:hover{border-color:var(--border-strong);transform:translateY(-2px)}
  .skill-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:.4rem}
  .skill-name{font-weight:600;font-size:.98rem}
  .skill-level{font-family:var(--font-mono);font-size:.75rem;color:var(--text-faint)}
  .skill-desc{font-size:.85rem;margin-bottom:.75rem}
  .bar-track{height:5px;border-radius:999px;background:var(--border);overflow:hidden}
  .bar-fill{height:100%;border-radius:999px;background:linear-gradient(90deg,var(--blue),var(--violet));width:0;transition:width 1.1s var(--ease)}

  .interest-chips{display:flex;flex-wrap:wrap;gap:.7rem;margin-top:.5rem}
  .chip{
    padding:.55rem 1.05rem;border-radius:999px;background:var(--surface);border:1px solid var(--border);
    font-size:.85rem;color:var(--text-muted);transition:border-color .25s,color .25s;
  }
  .chip:hover{border-color:var(--blue-bright);color:var(--text)}

  /* ============ PROJECTS ============ */
  .project-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.6rem}
  @media(max-width:900px){.project-grid{grid-template-columns:1fr}}
  .project-card{
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-l);
    padding:2rem;position:relative;overflow:hidden;transition:border-color .35s, transform .35s;
  }
  .project-card:hover{border-color:var(--border-strong);transform:translateY(-4px)}
  .project-card::before{
    content:"";position:absolute;top:0;left:0;right:0;height:2px;
    background:linear-gradient(90deg,var(--blue),var(--violet));opacity:0;transition:opacity .35s;
  }
  .project-card:hover::before{opacity:1}
  .project-image{
    margin:-2rem -2rem 1.4rem;height:200px;overflow:hidden;position:relative;
    border-bottom:1px solid var(--border);
  }
  .project-image img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s var(--ease)}
  .project-card:hover .project-image img{transform:scale(1.04)}
  .project-icon{
    width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;
    background:linear-gradient(135deg,var(--blue-glow),var(--violet-glow));border:1px solid var(--border-strong);
    margin-bottom:1.3rem;
  }
  .project-image + .project-icon{margin-top:0}
  .project-icon svg{width:24px;height:24px;stroke:var(--blue-bright)}
  .project-cat{font-family:var(--font-mono);font-size:.72rem;color:var(--blue-bright);margin-bottom:.5rem}
  .project-card h3{margin-bottom:.7rem}
  .project-card p{font-size:.94rem;margin-bottom:1.1rem}
  .tag-row{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:1rem}
  .tag{font-size:.75rem;padding:.32rem .7rem;border-radius:7px;background:var(--surface-strong);border:1px solid var(--border);color:var(--text-muted)}
  .feature-list{display:grid;grid-template-columns:1fr 1fr;gap:.4rem .8rem;margin-top:.6rem}
  .feature-list li{font-size:.83rem;color:var(--text-muted);display:flex;gap:.5rem;align-items:flex-start}
  .feature-list li::before{content:"—";color:var(--text-faint);flex-shrink:0}

  /* ============ MINI PROJECTS ============ */
  .mini-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.1rem}
  @media(max-width:900px){.mini-grid{grid-template-columns:1fr 1fr}}
  @media(max-width:560px){.mini-grid{grid-template-columns:1fr}}
  .mini-card{
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-m);
    padding:1.4rem;transition:border-color .3s, transform .3s;
  }
  .mini-card:hover{border-color:var(--blue-bright);transform:translateY(-3px)}
  .mini-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:.7rem}
  .mini-icon{
    width:34px;height:34px;border-radius:9px;display:flex;align-items:center;justify-content:center;
    background:var(--surface-strong);border:1px solid var(--border-strong);flex-shrink:0;
  }
  .mini-icon svg{width:16px;height:16px;stroke:var(--blue-bright)}
  .mini-tag{font-family:var(--font-mono);font-size:.68rem;color:var(--text-faint)}
  .mini-card h4{font-family:var(--font-display);font-size:1rem;font-weight:600;margin-bottom:.4rem}
  .mini-card p{font-size:.85rem}

  /* ============ EDUCATION ============ */
  .edu-card{
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-l);
    padding:2.2rem;margin-bottom:1.4rem;
  }
  .edu-head{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.6rem;margin-bottom:1rem}
  .edu-school{font-size:.85rem;color:var(--blue-bright);font-family:var(--font-mono)}
  .topic-grid{display:flex;flex-wrap:wrap;gap:.6rem;margin-top:1.1rem}
  .pie-list{display:grid;grid-template-columns:1fr 1fr;gap:.5rem 1.2rem;margin-top:1rem}
  .pie-list li{font-size:.88rem;color:var(--text-muted);display:flex;gap:.55rem;align-items:flex-start}
  .pie-list li::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--gold);margin-top:.55rem;flex-shrink:0}
  @media(max-width:640px){.pie-list{grid-template-columns:1fr}}

  /* ============ CURRENT WORK ============ */
  .work-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.1rem}
  @media(max-width:900px){.work-grid{grid-template-columns:1fr 1fr}}
  @media(max-width:560px){.work-grid{grid-template-columns:1fr}}
  .work-card{
    background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-m);
    padding:1.4rem;font-size:.92rem;font-weight:500;display:flex;gap:.8rem;align-items:flex-start;
    transition:border-color .3s, transform .3s;
  }
  .work-card:hover{border-color:var(--blue-bright);transform:translateY(-3px)}
  .work-card .num{font-family:var(--font-mono);font-size:.78rem;color:var(--text-faint);flex-shrink:0}
  .work-tagline{margin-top:2.2rem;font-family:var(--font-mono);color:var(--blue-bright);font-size:.95rem;text-align:center}

  /* ============ JOURNEY TIMELINE ============ */
  .timeline{position:relative;padding-left:2.4rem}
  .timeline::before{content:"";position:absolute;left:9px;top:6px;bottom:6px;width:1px;background:var(--border-strong)}
  .tl-item{position:relative;padding-bottom:2.6rem}
  .tl-item:last-child{padding-bottom:0}
  .tl-item::before{
    content:"";position:absolute;left:-2.4rem;top:2px;width:19px;height:19px;border-radius:50%;
    background:var(--bg);border:2px solid var(--blue-bright);
  }
  .tl-item.future::before{border-color:var(--violet)}
  .tl-num{font-family:var(--font-mono);font-size:.78rem;color:var(--blue-bright);margin-bottom:.3rem}
  .tl-item h3{margin-bottom:.35rem}
  .tl-item p{font-size:.94rem}

  /* ============ SOFT SKILLS ============ */
  .soft-grid{display:flex;flex-wrap:wrap;gap:.8rem}
  .soft-chip{
    display:flex;align-items:center;gap:.6rem;padding:.8rem 1.3rem;border-radius:var(--radius-m);
    background:var(--surface);border:1px solid var(--border);font-size:.92rem;font-weight:500;
    transition:border-color .3s, transform .3s;
  }
  .soft-chip:hover{border-color:var(--blue-bright);transform:translateY(-2px)}
  .soft-chip .dotgold{width:6px;height:6px;border-radius:50%;background:var(--gold);flex-shrink:0}

  /* ============ GOAL ============ */
  .goal-card{
    position:relative;border-radius:var(--radius-l);padding:3.5rem;text-align:center;
    background:linear-gradient(160deg,var(--surface),transparent);border:1px solid var(--border);
    overflow:hidden;
  }
  .goal-card::before{
    content:"";position:absolute;width:340px;height:340px;background:var(--blue);opacity:.16;
    filter:blur(90px);border-radius:50%;top:-120px;left:50%;transform:translateX(-50%);
  }
  .goal-card h2{max-width:760px;margin:0 auto 1.2rem;position:relative}
  .goal-card p{max-width:640px;margin:0 auto;position:relative;font-size:1.03rem}

  /* ============ CONTACT ============ */
  .contact-grid{display:grid;grid-template-columns:1fr 1.15fr;gap:3rem}
  @media(max-width:900px){.contact-grid{grid-template-columns:1fr}}
  .contact-info p{margin-bottom:1.8rem;font-size:1.02rem;max-width:400px}
  .social-list{display:flex;flex-direction:column;gap:.8rem}
  .social-item{
    display:flex;align-items:center;gap:.85rem;padding:.9rem 1.1rem;border-radius:var(--radius-m);
    background:var(--surface);border:1px solid var(--border);font-size:.92rem;
    transition:border-color .3s, transform .3s;
  }
  .social-item:hover{border-color:var(--blue-bright);transform:translateX(4px)}
  .social-item svg{width:19px;height:19px;flex-shrink:0;color:var(--blue-bright)}
  .social-meta{display:flex;flex-direction:column}
  .social-meta strong{font-size:.88rem}
  .social-meta span{font-size:.78rem;color:var(--text-faint)}

  .form-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-l);padding:2.2rem}
  .form-row{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.1rem}
  @media(max-width:520px){.form-row{grid-template-columns:1fr}}
  .field{display:flex;flex-direction:column;gap:.45rem;margin-bottom:1.1rem}
  .field label{font-size:.83rem;color:var(--text-muted);font-weight:500}
  .field input,.field textarea{
    background:var(--bg-alt);border:1px solid var(--border);border-radius:var(--radius-s);
    padding:.8rem 1rem;color:var(--text);transition:border-color .25s;
  }
  .field input:focus,.field textarea:focus{border-color:var(--blue-bright)}
  .field textarea{resize:vertical;min-height:120px}
  .form-msg{margin-top:1rem;font-size:.88rem;display:none}
  .form-msg.show{display:block}
  .form-msg.ok{color:var(--success)}

  /* ============ FOOTER ============ */
  footer{border-top:1px solid var(--border);padding:2.6rem 0}
  .footer-inner{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:1rem}
  .footer-brand{font-family:var(--font-display);font-weight:600}
  .footer-role{font-size:.85rem;color:var(--text-muted);margin-top:.2rem}
  .footer-copy{font-size:.82rem;color:var(--text-faint);font-family:var(--font-mono)}

  /* ============ SCROLL TOP ============ */
  .scroll-top{
    position:fixed;bottom:1.8rem;right:1.8rem;width:46px;height:46px;border-radius:50%;
    background:linear-gradient(135deg,var(--blue),var(--violet));display:flex;align-items:center;justify-content:center;
    box-shadow:0 10px 30px -8px var(--blue-glow);opacity:0;pointer-events:none;transform:translateY(12px);
    transition:opacity .3s var(--ease), transform .3s var(--ease);z-index:90;
  }
  .scroll-top.show{opacity:1;pointer-events:auto;transform:translateY(0)}
  .scroll-top svg{width:18px;height:18px;color:#fff}
</style>
</head>
