<button class="scroll-top" id="scrollTop" aria-label="Scroll to top">
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg>
</button>

<script>
(function(){
  "use strict";

  /* ---------- THEME TOGGLE (in-memory, no storage APIs) ---------- */
  var root = document.documentElement;
  document.getElementById('themeToggle').addEventListener('click', function(){
    var next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
  });

  /* ---------- MOBILE NAV ---------- */
  var navToggle = document.getElementById('navToggle');
  var navLinks = document.getElementById('navLinks');
  navToggle.addEventListener('click', function(){
    navToggle.classList.toggle('open');
    navLinks.classList.toggle('open');
  });
  navLinks.querySelectorAll('a').forEach(function(a){
    a.addEventListener('click', function(){
      navToggle.classList.remove('open');
      navLinks.classList.remove('open');
    });
  });

  /* ---------- STICKY NAVBAR + SCROLL TOP BUTTON ---------- */
  var navbar = document.getElementById('navbar');
  var scrollTopBtn = document.getElementById('scrollTop');
  window.addEventListener('scroll', function(){
    var y = window.scrollY;
    navbar.classList.toggle('scrolled', y > 30);
    scrollTopBtn.classList.toggle('show', y > 500);
  }, { passive: true });
  scrollTopBtn.addEventListener('click', function(){
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  /* ---------- ACTIVE NAV LINK (scroll spy) ---------- */
  var sections = Array.from(document.querySelectorAll('section, header.hero'));
  var navItems = document.querySelectorAll('[data-nav]');
  var spy = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var id = entry.target.getAttribute('id');
        navItems.forEach(function(link){
          link.classList.toggle('active', link.getAttribute('href') === '#' + id);
        });
      }
    });
  }, { rootMargin: '-45% 0px -50% 0px', threshold: 0 });
  sections.forEach(function(s){ spy.observe(s); });

  /* ---------- REVEAL ON SCROLL ---------- */
  var revealEls = document.querySelectorAll('.reveal');
  var revealObserver = new IntersectionObserver(function(entries, obs){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        entry.target.classList.add('in-view');
        obs.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15 });
  revealEls.forEach(function(el){ revealObserver.observe(el); });

  /* ---------- SKILL BAR FILL (animate once visible) ---------- */
  var barObserver = new IntersectionObserver(function(entries, obs){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var fill = entry.target;
        fill.style.width = fill.getAttribute('data-level') + '%';
        obs.unobserve(fill);
      }
    });
  }, { threshold: 0.4 });
  document.querySelectorAll('.bar-fill').forEach(function(el){ barObserver.observe(el); });

  /* ---------- SKILLS TABS ---------- */
  var tabBtns = document.querySelectorAll('.tab-btn');
  var panels = document.querySelectorAll('.skills-panel');
  tabBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      tabBtns.forEach(function(b){ b.classList.remove('active'); });
      panels.forEach(function(p){ p.classList.remove('active'); });
      btn.classList.add('active');
      var target = document.querySelector('[data-panel="' + btn.getAttribute('data-tab') + '"]');
      target.classList.add('active');
      target.querySelectorAll('.bar-fill').forEach(function(fill){
        fill.style.width = fill.getAttribute('data-level') + '%';
      });
    });
  });

  /* ---------- ROTATING ROLE LINE ---------- */
  var roles = ['Aspiring Web Developer', 'Digital Development Student', 'Future Full-Stack Developer'];
  var roleEl = document.getElementById('roleWord');
  var roleIndex = 0;
  setInterval(function(){
    roleEl.classList.add('swap');
    setTimeout(function(){
      roleIndex = (roleIndex + 1) % roles.length;
      roleEl.textContent = roles[roleIndex];
      roleEl.classList.remove('swap');
    }, 350);
  }, 2800);

  /* ---------- TERMINAL TYPEWRITER ---------- */
  var terminalLines = [
    { html: '<span class="prompt">$</span> whoami' },
    { html: '<span class="out">ilyas_yekhlef</span>', pause: true },
    { html: '<span class="prompt">$</span> cat status.txt' },
    { html: '<span class="out">Digital Development Student</span>' },
    { html: '<span class="out">Aspiring Web Developer</span>' },
    { html: '<span class="out">Location: Tangier, Morocco</span>', pause: true },
    { html: '<span class="prompt">$</span> ./availability --check' },
    { html: '<span class="ok">&#10003; Available for opportunities</span>' }
  ];
  var terminalBody = document.getElementById('terminalBody');

  function typeLine(text, el, speed, cb){
    var i = 0;
    (function tick(){
      el.innerHTML = text.slice(0, i);
      i++;
      if(i <= text.length){
        setTimeout(tick, speed);
      } else if(cb){ cb(); }
    })();
  }

  function runTerminal(index){
    if(index >= terminalLines.length){
      var cursor = document.createElement('span');
      cursor.className = 'cursor';
      terminalBody.appendChild(cursor);
      return;
    }
    var line = terminalLines[index];
    var div = document.createElement('div');
    div.className = 'terminal-line';
    terminalBody.appendChild(div);
    typeLine(line.html, div, 18, function(){
      setTimeout(function(){ runTerminal(index + 1); }, line.pause ? 420 : 160);
    });
  }

  var terminalStarted = false;
  var terminalObserver = new IntersectionObserver(function(entries, obs){
    entries.forEach(function(entry){
      if(entry.isIntersecting && !terminalStarted){
        terminalStarted = true;
        runTerminal(0);
        obs.disconnect();
      }
    });
  }, { threshold: 0.3 });
  terminalObserver.observe(document.querySelector('.terminal'));

  /* ---------- CONTACT FORM (front-end only) ---------- */
  var form = document.getElementById('contactForm');
  var formMsg = document.getElementById('formMsg');
  form.addEventListener('submit', function(e){
    e.preventDefault();
    formMsg.textContent = "Thanks for reaching out — I'll get back to you soon. (Connect this form to an email service or backend to receive real messages.)";
    formMsg.className = 'form-msg show ok';
    form.reset();
  });

})();
</script>
